5	/**
6	 * Seller identity + number prefix printed on an invoice, resolved from Settings →
7	 * General/Billing. Read once per render and handed to the (synchronous) renderer.
8	 */
9	export type InvoiceBranding = {
10	  /** `invoice_prefix`, never blank — see `invoiceBranding()`. */
11	  numberPrefix: string;
12	  /** `brand_name`, never blank. */
13	  brandName: string;
14	  /** `company_legal_name` — "" means "omit the seller block". */
15	  legalName: string;
16	  /** `company_address` — "" means "omit the seller address". */
17	  address: string;
18	};
19	
20	const FALLBACK_BRANDING: InvoiceBranding = {
21	  numberPrefix: SETTINGS_DEFAULTS.invoice_prefix,
22	  brandName: SETTINGS_DEFAULTS.brand_name,
23	  legalName: "",
24	  address: "",
25	};
26	
27	/**
28	 * Read the invoice branding from Settings.
29	 *
30	 * `numberPrefix` is forced non-empty. `Invoice.number` is a bare autoincrement, so an
31	 * operator who clears the field would otherwise produce documents identified only as
32	 * "00012" — not quotable to a customer, not greppable in a mailbox, and impossible to
33	 * tell apart from a server ID or an order number in a support thread.
34	 *
35	 * `legalName`/`address` stay blank-able by design: the seller block is omitted entirely
36	 * when they are unset, rather than printing an empty "From" heading. That is why the
37	 * "shown on invoices" claim on the admin field is now true without the panel having to
38	 * demand a value it does not have.
39	 */
40	export async function invoiceBranding(): Promise<InvoiceBranding> {
41	  const [prefix, brandName, legalName, address] = await Promise.all([
42	    getSetting("invoice_prefix"),
43	    getSetting("brand_name"),
44	    getSetting("company_legal_name"),
45	    getSetting("company_address"),
46	  ]);
47	  return {
48	    numberPrefix: prefix.trim() || SETTINGS_DEFAULTS.invoice_prefix,
49	    brandName: brandName.trim() || SETTINGS_DEFAULTS.brand_name,
50	    legalName: legalName.trim(),
51	    address: address.trim(),
52	  };
53	}
