55	/**
56	 * The customer-facing invoice identifier: the configured prefix plus the zero-padded
57	 * autoincrement (`INV-00012`).
58	 *
59	 * One function so every surface agrees. The padding was previously duplicated as
60	 * `#${String(n).padStart(5, "0")}` at eight call sites, which is precisely why
61	 * `invoice_prefix` had no reader — there was no single place to wire it. The `#` sigil
62	 * is dropped now that a prefix is always present; keeping both would render `#INV-00012`.
63	 */
64	export function formatInvoiceNumber(
65	  number: number,
66	  prefix: string = SETTINGS_DEFAULTS.invoice_prefix,
67	): string {
68	  return `${prefix}${String(number).padStart(5, "0")}`;
69	}
