132	/**
133	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
134	 * a charge site can create the invoice inside its own guarded `$transaction`
135	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
136	 * The stored total (`amountCents`) is always derived from line items + tax so
137	 * callers can't desync the stamped total from the itemised breakdown.
138	 */
139	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
140	  const items = opts.lineItems.map((li) => ({
141	    description: String(li.description),
142	    qty: Number(li.qty) || 0,
143	    unitCents: Math.round(Number(li.unitCents) || 0),
144	    amountCents: Math.round(
145	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
146	    ),
147	  }));
148	  const taxCents = Math.round(opts.taxCents ?? 0);
149	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
150	  const amountCents = subtotalCents + taxCents;
151	  const status = opts.status ?? "OPEN";
152	
153	  return {
154	    userId: opts.userId,
155	    description: opts.description,
156	    lineItems: items,
157	    taxCents,
158	    amountCents,
159	    status,
160	    paidAt: status === "PAID" ? new Date() : null,
161	    periodStart: opts.period?.start ?? null,
162	    periodEnd: opts.period?.end ?? null,
163	  };
164	}
